def test_criteria_to_query_all_fields() -> None:
    criteria = {
        "from": "a@x.com",
        "to": "me",
        "subject": "hi there",
        "query": "foo OR bar",
        "negatedQuery": "baz",
        "hasAttachment": True,
        "excludeChats": True,
        "size": 1000,
        "sizeComparison": "larger",
    }
    assert cli.criteria_to_query(criteria) == (
        "from:(a@x.com) to:(me) subject:(hi there) (foo OR bar) -(baz) "
        "has:attachment -in:chats larger:1000"
    )


def test_criteria_to_query_ignores_unspecified_size() -> None:
    criteria = {"size": 1000, "sizeComparison": "unspecified", "from": "a"}
    assert cli.criteria_to_query(criteria) == "from:(a)"


def fake_gmail(matching_queries: set[str], *, message_exists: bool = True) -> Any:
    """Stand-in for run_gws: messages.list matches only the given filter queries."""

    def run(resource_args: list[str], params: dict[str, Any]) -> dict[str, Any]:
        if resource_args[-2:] == ["filters", "list"]:
            return FILTERS
        if resource_args[-2:] == ["labels", "list"]:
            return {"labels": [{"id": "Label_7", "name": "Reports"}]}
        assert params["includeSpamTrash"] is True
        prefix = f"rfc822msgid:{MESSAGE_ID}"
        if params["q"] == prefix:
            return {"messages": [{"id": "1"}]} if message_exists else {}
        inner = params["q"].removeprefix(prefix + " (").removesuffix(")")
        return {"messages": [{"id": "1"}]} if inner in matching_queries else {}

    return run


@pytest.mark.parametrize("jobs", [1, 4])
def test_find_matching_filters_returns_every_match_in_order(
    jobs: int, caplog: pytest.LogCaptureFixture
) -> None:
    matching = {"from:(alerts@example.com)", "(list:dev.example.com)"}
    caplog.set_level("INFO", logger="find_gmail_filter")
    with patch.object(cli, "run_gws", side_effect=fake_gmail(matching)):
        assert cli.find_matching_filters(MESSAGE_ID, jobs=jobs) == [
            FILTERS["filter"][0],
            FILTERS["filter"][2],
        ]
    assert f"Looking up message {MESSAGE_ID}" in caplog.text
    assert "Checked 1/3 filters, 1 matched so far" in caplog.text
    assert "Checked 3/3" not in caplog.text
    assert "Matched 2 of 3 filters" in caplog.text


