def test_run_gws_passes_params_as_json() -> None:
    ok = subprocess.CompletedProcess(
        args=[], returncode=0, stdout='{"a": 1}', stderr=""
    )
    with patch.object(cli.subprocess, "run", return_value=ok) as mock_run:
        assert cli.run_gws(["gmail", "x"], {"userId": "me"}) == {"a": 1}
    command = mock_run.call_args.args[0]
    assert command[:2] == ["gws", "gmail"]
    assert json.loads(command[-1]) == {"userId": "me"}


